const MD_dbl=(x1,y1,x2,y2,col,w=3)=>MD_arrow((x1+x2)/2,(y1+y2)/2,x1,y1,col,w,14)+MD_arrow((x1+x2)/2,(y1+y2)/2,x2,y2,col,w,14);
const MD_s=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
const MD_poly=(pts,col,w=4,ex='')=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const MD_range=(a,b,n)=>Array.from({length:n+1},(_,i)=>a+(b-a)*i/n);
