const Sut=MD_s('S','ut'), Syt=MD_s('S','yt'), Se=MD_s('S','e'), Sep='S<tspan baseline-shift="sub" font-size="70%">e</tspan>′', sgm=MD_s('σ','m'), sga=MD_s('σ','a'), dst=MD_s('δ','st'), Kf=MD_s('K','f');
