/* the S-N line of the lessons (log10 S against log10 N): from (10^3, 0.9 Sut) to (10^6, Se), flat after */
const MD_snS=(lgN,Su,Sen)=>lgN<=6?Math.pow(10,Math.log10(0.9*Su)+(Math.log10(Sen/(0.9*Su))/3)*(lgN-3)):Sen;
/* a small log-log S-N frame: x for log10 N in [3,7], y for S in [lo,hi] MPa */
const MD_snFrame=(x0,y0,w,h,lo,hi)=>({x:l=>x0+(l-3)/4*w,y:S=>y0-(Math.log10(S)-Math.log10(lo))/(Math.log10(hi)-Math.log10(lo))*h});
/* the Haigh diagram (σm across, σa up) at k px per MPa from origin (x0,y0) */
const MD_hx=(x0,k)=>m=>x0+m*k, MD_hy=(y0,k)=>a=>y0-a*k;
const MD_gerber=(Se_,Su,X,Y,to=Su)=>MD_range(0,to,40).map(m=>[X(m),Y(Se_*(1-(m/Su)**2))]);
