const MD_rod=(cx,y0,len,col=MD_STEEL)=>`<rect x="${cx-7}" y="${y0}" width="14" height="${len}" rx="3" fill="${col}"/><rect x="${cx-26}" y="${y0+len}" width="52" height="12" rx="3" fill="${MD_DARK}"/>`;
const MD_wt=(cx,y,lab='W')=>MD_box(cx-34,y,68,46,{fill:'#E6FCF5',st:GRN,sw:3,r:8})+MD_T(cx,y+32,lab,{fs:24,fw:800,a:'middle',fill:GRN});
