const MD_ceil=(x1,x2,y)=>{let s=`<rect x="${x1}" y="${y-10}" width="${x2-x1}" height="10" fill="${MD_MID}"/>`;for(let x=x1+6;x<x2;x+=18)s+=MD_L(x,y-10,x+10,y-22,MD_MID,2);return s};

